INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(71200730, 'Despair from the Dark', '出于黑暗的绝望', '闇より出でし絶望', 'Effect Monster', 'Zombie', 'DARK', 8, 2800, 3000, '①：这张卡被对方的效果从手卡·卡组送去墓地的场合发动。这张卡特殊召唤。'),
(76728962, 'Desperado Barrel Dragon', '亡命左轮手枪龙', 'デスペラード・リボルバー・ドラゴン', 'Effect Monster', 'Machine', 'DARK', 8, 2800, 2200, '①：自己场上的机械族·暗属性怪兽被战斗·效果破坏的场合才能发动。这张卡从手卡特殊召唤。 ②：1回合1次，自己·对方的战斗阶段才能发动。进行3次投掷硬币。选最多有表出现数量的场上的表侧表示怪兽破坏。3次都是表的场合，再让自己从卡组抽1张。这个效果发动的回合，这张卡不能攻击。 ③：这张卡被送去墓地的场合才能发动。把持有进行投掷硬币效果的1只7星以下的怪兽从卡组加入手卡。'),
(34149830, 'Desperate Tag', '死力的组队换手', '死力のタッグ・チェンジ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上表侧攻击表示存在的怪兽被战斗破坏的伤害计算时，可以把那次战斗发生的对自己的战斗伤害变成0，那次伤害步骤结束时从手卡把1只4星以下的战士族怪兽特殊召唤。'),
(99543666, 'Despia, Theater of the Branded', '烙印剧城 惨绝戏', '烙印劇城デスピア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只8星以上的融合怪兽融合召唤。 ②：融合怪兽以外的自己场上的表侧表示的天使族怪兽因对方的效果从场上离开的场合或者被战斗破坏的场合，以自己墓地1只8星以上的融合怪兽为对象才能发动。那只怪兽特殊召唤。'),
(90179822, 'Despian Comedy', '喜剧之惨绝戏子', '喜劇のデスピアン', 'Effect Monster', 'Fairy', 'DARK', 1, NULL, 2000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上的表侧表示的「死狱乡」卡为对象的魔法·陷阱·怪兽的效果由对方发动时，把这张卡从手卡丢弃才能发动。那个效果无效。 ②：自己·对方回合，这张卡在墓地存在的场合，把自己场上1只融合怪兽解放才能发动。这张卡特殊召唤。'),
(53971455, 'Despian Luluwalilith', '惨绝戏子・赫圣之妖骑士', '赫聖の妖騎士', 'Synchro Monster', 'Spellcaster', 'LIGHT', 12, 2500, 2500, '4星调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己·对方的卡从额外卡组离开的场合才能发动。自己场上的全部怪兽的攻击力上升500。那之后，可以把场上1张表侧表示卡的效果直到回合结束时无效。 ②：这张卡被送去墓地的回合的结束阶段才能发动。从手卡·卡组把攻击力和守备力的数值相同的1只魔法师族·光属性怪兽特殊召唤。'),
(18666161, 'Despian Proskenion', '惨绝戏子・镜框舞台', 'デスピアン・プロスケニオン', 'Fusion Monster', 'Fiend', 'LIGHT', 11, 3200, 3200, '「死狱乡」怪兽＋光属性怪兽＋暗属性怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以对方墓地1只融合·同调·超量·连接怪兽为对象才能发动。那只怪兽除外或在自己场上特殊召唤。 ②：这张卡战斗破坏对方怪兽时才能发动。给与对方那只怪兽的原本攻击力和原本守备力之内较高方数值的伤害。'),
(72272462, 'Despian Quaeritis', '惨绝戏子・汝寻何人', 'デスピアン・クエリティス', 'Fusion Monster', 'Fiend', 'LIGHT', 8, 2500, 2500, '「死狱乡」怪兽＋光·暗属性怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。除8星以上的融合怪兽外的场上的全部怪兽的攻击力直到回合结束时变成0。 ②：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。从卡组选1只「死狱乡」怪兽或者「阿不思的落胤」加入手卡或特殊召唤。'),
(36577931, 'Despian Tragedy', '悲剧之惨绝戏子', '悲劇のデスピアン', 'Effect Monster', 'Fairy', 'DARK', 1, 400, 400, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡被效果送去墓地的场合或者被效果除外的场合才能发动。从卡组把「悲剧之死狱乡演员」以外的1只「死狱乡」怪兽加入手卡。 ②：把墓地的这张卡除外，以自己墓地1张「烙印」魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(72192100, 'Desrook Archfiend', '死亡城堡恶魔', 'デスルークデーモン', 'Effect Monster', 'Fiend', 'LIGHT', 3, 1100, 1800, '这张卡的控制者在自己的每1个准备阶段支付500基本分。当这张卡成为对方所控制的卡的效果对象时，在效果处理时掷1次骰子，若掷出3，则使此效果无效并将其破坏。当自己场上的「灭绝国王恶魔」被破坏送去墓地时，可以从手卡将这张卡送去墓地，将此「灭绝国王恶魔」特殊召唤上场。'),
(22634473, 'Destined Rivals', '对峙的宿命', '対峙する宿命', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「青眼白龙」或「黑魔术师」存在的场合才能发动。对方场上的全部表侧表示怪兽的效果直到回合结束时无效化。'),
(94212438, 'Destiny Board', '通灵盘', 'ウィジャ盤', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡和「死之信息」卡4种类在自己场上齐集时，自己决斗胜利。 ①：对方结束阶段把这个效果发动。从手卡·卡组让1张「死之信息」卡以「E」「A」「T」「H」的顺序在自己的魔法与陷阱区域出现。 ②：自己场上的「通灵盘」或者「死之信息」卡从场上离开时自己场上的「通灵盘」以及「死之信息」卡全部送去墓地。'),
(45809008, 'Destiny Draw', '命运抽牌', 'デステニー・ドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1张「命运英雄」卡才能发动。自己从卡组抽2张。'),
(300201002, 'Destiny Draw (Skill Card)', NULL, NULL, 'Skill Card', 'Yugi', NULL, NULL, NULL, NULL, NULL),
(76263644, 'Destiny End Dragoon', '龙骑兵 D-终结', 'Dragoon D-END', 'Fusion Monster', 'Warrior', 'DARK', 10, 3000, 3000, '「命运英雄 血魔-D」＋「命运英雄 教义人」 这张卡的融合召唤不用上记的卡不能进行。 ①：1回合1次，以对方场上1只怪兽为对象才能发动。那只对方怪兽破坏，把表侧表示怪兽破坏的场合，给与对方那个攻击力数值的伤害。这个效果发动的回合，自己不能进行战斗阶段。 ②：这张卡在墓地存在的场合，自己准备阶段把自己墓地1张「命运英雄」卡除外才能发动。这张卡从墓地特殊召唤。'),
(55461064, 'Destiny HERO - Blade Master', '命运英雄 匕首人', 'D-HERO ダガーガイ', 'Effect Monster', 'Warrior', 'DARK', 3, 300, 600, '对方的战斗阶段时，从手卡把这张卡丢弃才能发动。自己场上的全部名字带有「命运英雄」的怪兽的攻击力直到结束阶段时上升800。'),
(77608643, 'Destiny HERO - Captain Tenacious', '命运英雄 顽强人', 'D-HERO ダイハードガイ', 'Effect Monster', 'Warrior', 'DARK', 3, 800, 800, '这张卡在自己场上表侧表示存在时，自己场上除这张卡以外的名字带有「命运英雄」的怪兽被战斗破坏送去墓地的场合，可以把那1只怪兽在下次自己的准备阶段时在自己场上特殊召唤。这个效果1回合只能使用1次。'),
(63362460, 'Destiny HERO - Celestial', '命运－英雄 神性魔侠', 'D-HERO ディバインガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 1400, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击宣言时，以对方场上1张表侧表示的魔法卡为对象才能发动。那张卡破坏，给与对方500伤害。 ②：自己手卡是0张的场合，从自己墓地把这张卡和1只「命运英雄」怪兽除外才能发动。自己从卡组抽2张。这个效果在这张卡送去墓地的回合不能发动。'),
(30757127, 'Destiny HERO - Dangerous', '命运－英雄 绝命魔侠', 'D-HERO デッドリーガイ', 'Fusion Monster', 'Warrior', 'DARK', 6, 2000, 2600, '「命运英雄」怪兽＋暗属性效果怪兽 这个卡名的效果1回合只能使用1次。 ①：自己·对方回合，丢弃1张手卡才能发动。从手卡·卡组把1只「命运英雄」怪兽送去墓地。那之后，自己墓地有「命运英雄」怪兽存在的场合，自己场上的全部「命运英雄」怪兽的攻击力直到回合结束时上升自己墓地的「命运英雄」怪兽数量×200。'),
(26964762, 'Destiny HERO - Dark Angel', '命运－英雄 暗黑天使', 'D-HERO ダークエンジェル', 'Effect Monster', 'Warrior', 'DARK', 1, NULL, NULL, '①：自己墓地的「命运英雄」怪兽是3只以上的场合，把这张卡从手卡丢弃，以自己墓地1只「命运英雄」怪兽为对象才能发动。那只怪兽在对方场上守备表示特殊召唤。 ②：只要这张卡在怪兽区域存在，自己发动的魔法卡的效果无效化并破坏。 ③：自己准备阶段，从自己墓地把这张卡和1只「命运英雄」怪兽除外才能发动。双方各自从自身卡组选1张通常魔法卡在卡组最上面放置。'),
(81866673, 'Destiny HERO - Dasher', '命运－英雄 冲刺魔侠', 'D-HERO ダッシュガイ', 'Effect Monster', 'Warrior', 'DARK', 6, 2100, 1000, '①：1回合1次，把自己场上1只怪兽解放才能发动。这张卡的攻击力直到回合结束时上升1000。 ②：这张卡攻击的场合，战斗阶段结束时变成守备表示。 ③：只在这张卡在墓地存在才有1次，自己在自己抽卡阶段抽卡时，那卡是怪兽的场合，把那1只怪兽给双方确认才能发动。这张卡在墓地存在的场合，那只确认的怪兽特殊召唤。'),
(64184058, 'Destiny HERO - Decider', '命运－英雄 决断魔侠', 'D-HERO ディシジョンガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 1000, '「命运英雄 决意人」的①③的效果在决斗中各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。这个回合的结束阶段，选自己墓地1只「英雄」怪兽加入手卡。 ②：6星以上的对方怪兽不能选择这张卡作为攻击对象。 ③：这张卡在墓地存在，给与自己伤害的魔法·陷阱·怪兽的效果发动时发动。这张卡回到手卡，那个效果让自己受到的伤害变成0。'),
(54749427, 'Destiny HERO - Defender', '命运英雄 防御人', 'D-HERO ディフェンドガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 100, 2700, '对方回合的准备阶段时这张卡表侧守备表示存在的场合，对方玩家抽1张卡。'),
(16605586, 'Destiny HERO - Denier', '命运－英雄 否决魔侠', 'D-HERO ディナイアルガイ', 'Effect Monster', 'Warrior', 'DARK', 3, 1100, 600, '这个卡名的①的效果1回合只能使用1次，②的效果在决斗中只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。选自己的卡组·墓地·除外状态的1只「命运英雄」怪兽在卡组最上面放置。 ②：这张卡在墓地存在，自己的场上或墓地有「命运英雄 否定人」以外的「命运英雄」怪兽存在的场合才能发动。这张卡特殊召唤。'),
(39829561, 'Destiny HERO - Departed', '命运英雄 死逝人', 'D-HERO ディパーテッドガイ', 'Effect Monster', 'Warrior', 'DARK', 2, 1000, NULL, '自己的准备阶段时，这张卡在墓地存在的场合，在对方场上表侧攻击表示特殊召唤。这张卡被战斗破坏的场合，不去墓地从游戏中除外。这张卡从手卡·卡组被卡的效果送去墓地的场合，不去墓地从游戏中除外。'),
(60461804, 'Destiny HERO - Destroyer Phoenix Enforcer', '命运－英雄 毁灭不死鸟魔侠', 'D-HERO デストロイフェニックスガイ', 'Fusion Monster', 'Warrior', 'DARK', 8, 2500, 2100, '6星以上的「英雄」怪兽＋「命运英雄」怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：对方场上的怪兽的攻击力下降自己墓地的「英雄」卡数量×200。 ②：自己·对方回合可以发动。自己场上1张卡和场上1张卡破坏。 ③：这张卡被战斗·效果破坏的场合才能发动。下个回合的准备阶段，从自己墓地把1只「命运英雄」怪兽特殊召唤。'),
(13093792, 'Destiny HERO - Diamond Dude', '命运－英雄 钻石魔侠', 'D-HERO ダイヤモンドガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1400, 1600, '①：1回合1次，自己主要阶段才能发动。自己卡组最上面的卡翻开，那是通常魔法卡的场合，那张卡送去墓地。不是的场合，那张卡回到卡组最下面。这个效果把通常魔法卡送去墓地的场合，下次的自己回合的主要阶段可以把墓地的那张通常魔法卡的发动时的效果发动。'),
(56570271, 'Destiny HERO - Disk Commander', '命运－英雄 光盘魔侠', 'D-HERO ディスクガイ', 'Effect Monster', 'Warrior', 'DARK', 1, 300, 300, '这个卡名的效果在决斗中只能使用1次。这张卡在送去墓地的回合不能作从墓地的特殊召唤。 ①：这张卡从墓地的特殊召唤成功的场合才能发动。自己从卡组抽2张。'),
(17132130, 'Destiny HERO - Dogma', '命运－英雄 教义魔侠', 'D-HERO ドグマガイ', 'Effect Monster', 'Warrior', 'DARK', 8, 3400, 2400, '这张卡不能通常召唤。把包含「命运英雄」怪兽的自己场上3只怪兽解放的场合才能特殊召唤。 ①：这个方法让这张卡特殊召唤成功的场合，下次的对方准备阶段发动。对方基本分变成一半。'),
(69394324, 'Destiny HERO - Dominance', '命运－英雄 统治魔侠', 'D-HERO ドミネイトガイ', 'Fusion Monster', 'Warrior', 'DARK', 10, 2900, 2600, '「命运英雄」怪兽×3 这个卡名的①②③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从自己或者对方的卡组上面把5张卡确认，用喜欢的顺序回到卡组上面。 ②：这张卡战斗破坏对方怪兽时才能发动。自己从卡组抽1张。 ③：融合召唤的这张卡被战斗·效果破坏的场合，以自己墓地3只9星以下的「命运英雄」怪兽为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤。'),
(41613948, 'Destiny HERO - Doom Lord', '命运英雄 恶魔人', 'D-HERO デビルガイ', 'Effect Monster', 'Warrior', 'DARK', 3, 600, 800, '这张卡在自己场上表侧攻击表示存在的场合，1回合只有1次，可以把1只对方怪兽从游戏中除外。使用这个效果的玩家在这个回合不能进行战斗。这个效果除外的怪兽在第2次自己的准备阶段时以相同的表示形式回到对方场上。'),
(28355718, 'Destiny HERO - Double Dude', '命运英雄 双身人', 'D-HERO ダブルガイ', 'Effect Monster', 'Warrior', 'DARK', 6, 1000, 1000, '这张卡不能特殊召唤。这张卡在同1次的战斗阶段中可以作2次攻击。这张卡被破坏送去墓地的场合，下次的自己回合的准备阶段时，可以在自己场上把2只「双身人衍生物」（战士族·暗·4星·攻/守1000）特殊召唤。'),
(48150362, 'Destiny HERO - Drawhand', '命运－英雄 拔枪魔侠', 'D-HERO ドローガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「英雄」怪兽的效果特殊召唤成功的场合才能发动。双方玩家各自从卡组抽1张。 ②：这张卡被送去墓地的场合，下次的准备阶段才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(36625827, 'Destiny HERO - Dread Servant', '命运英雄 恐惧从者', 'D-HERO ドレッドサーヴァント', 'Effect Monster', 'Warrior', 'DARK', 3, 400, 700, '这张卡召唤成功时，「幽狱之时计塔」放置1个时计指示物。这张卡被战斗破坏送去墓地时，可以把自己场上1张魔法·陷阱卡破坏。'),
(40591390, 'Destiny HERO - Dreadmaster', '命运－英雄 恐惧魔侠', 'D-HERO ドレッドガイ', 'Effect Monster', 'Warrior', 'DARK', 8, -1, -1, '「幽狱之时计塔」的效果特殊召唤的场合，自己场上名字带有「命运英雄」的怪兽以外的自己怪兽全部破坏。那之后，可以从自己墓地把最多2只名字带有「命运英雄」的怪兽特殊召唤。这张卡特殊召唤的回合，自己场上的名字带有「命运英雄」的怪兽不会被破坏，对控制者的战斗伤害变成0。这张卡的攻击力·守备力变成自己场上除这张卡外的名字带有「命运英雄」的怪兽的原本攻击力合计数值。'),
(66262416, 'Destiny HERO - Dreamer', '命运英雄 梦乡人', 'D-HERO ドリームガイ', 'Effect Monster', 'Warrior', 'DARK', 1, NULL, 600, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己的「命运英雄」怪兽进行战斗的伤害计算时才能发动。这张卡从墓地特殊召唤，那只自己怪兽不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害变成0。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(91691605, 'Destiny HERO - Drilldark', '命运－英雄 钻头魔侠', 'D-HERO ドリルガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 1200, '「命运英雄 钻头人」的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。把持有这张卡的攻击力以下的攻击力的1只「命运英雄」怪兽从手卡特殊召唤。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(93431862, 'Destiny HERO - Dunker', '命运英雄 扣杀人', 'D-HERO ダンクガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1200, 1700, '可以从手卡把1张名字带有「命运英雄」的卡送去墓地，给与对方基本分500分伤害。'),
(93657021, 'Destiny HERO - Dusktopia', '命运英雄 暮托邦人', 'D-HERO ダスクユートピアガイ', 'Fusion Monster', 'Warrior', 'DARK', 10, 3000, 3000, '「命运英雄」融合怪兽＋「命运英雄」怪兽 ①：这张卡融合召唤成功的场合才能发动。从自己的手卡·场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：1回合1次，以场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被战斗·效果破坏，那只怪兽的战斗发生的双方的战斗伤害变成0。这个效果在对方回合也能发动。'),
(37780349, 'Destiny HERO - Dynatag', '命运－英雄 爆破魔侠', 'D-HERO ダイナマイトガイ', 'Effect Monster', 'Warrior', 'DARK', 5, 1000, 1000, '①：怪兽进行战斗的伤害计算时把这张卡从手卡丢弃才能发动。那次战斗发生的对自己的战斗伤害变成0，双方玩家受到1000伤害。 ②：把墓地的这张卡除外，以自己场上1只「命运英雄」怪兽为对象才能发动。那只怪兽的攻击力直到下次的对方回合结束时上升1000。'),
(90579153, 'Destiny HERO - Dystopia', '命运－英雄 敌托邦魔侠', 'D-HERO ディストピアガイ', 'Fusion Monster', 'Warrior', 'DARK', 8, 2800, 2400, '「命运英雄」怪兽×2 「命运英雄 敌托邦人」的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以自己墓地1只4星以下的「命运英雄」怪兽为对象才能发动。给与对方那只怪兽的攻击力数值的伤害。 ②：这张卡的攻击力和原本攻击力不同的场合，以场上1张卡为对象才能发动。那张卡破坏，这张卡的攻击力变成原本数值。这个效果在对方回合也能发动。'),
(80744121, 'Destiny HERO - Fear Monger', '命运英雄 破灭人', 'D-HERO ドゥームガイ', 'Effect Monster', 'Warrior', 'DARK', 4, 1000, 1000, '这张卡被战斗破坏送去墓地的场合，下次自己回合的准备阶段时，自己墓地存在的「命运英雄 破灭人」以外的1只名字带有「命运英雄」的怪兽在自己场上特殊召唤。'),
(9411399, 'Destiny HERO - Malicious', '命运－英雄 邪虐魔侠', 'D-HERO ディアボリックガイ', 'Effect Monster', 'Warrior', 'DARK', 6, 800, 800, '①：把墓地的这张卡除外才能发动。从卡组把1只「命运英雄 魔性人」特殊召唤。'),
(83965310, 'Destiny HERO - Plasma', '命运－英雄 血魔-D', 'D-HERO Bloo-D', 'Effect Monster', 'Warrior', 'DARK', 8, 1900, 600, '这张卡不能通常召唤。把自己场上3只怪兽解放的场合才能特殊召唤。 ①：只要这张卡在怪兽区域存在，对方场上的表侧表示怪兽的效果无效化。 ②：1回合1次，以对方场上1只怪兽为对象才能发动。那只对方怪兽当作装备魔法卡使用给这张卡装备（只有1只可以装备）。 ③：这张卡的攻击力上升这张卡的效果装备的怪兽的原本攻击力一半数值。'),
(15294090, 'Destiny Mirage', '命运幻象', 'デステニー・ミラージュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上名字带有「命运英雄」的怪兽被对方的卡的效果破坏送去墓地时才能发动。把这个回合被破坏送去墓地的名字带有「命运英雄」的怪兽全部在自己场上特殊召唤。'),
(35464895, 'Destiny Signal', '命运标记', 'デステニー・シグナル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的怪兽被战斗破坏送去墓地时才能发动。从自己的手卡·卡组特殊召唤1只名字带有「命运英雄」的4星以下的怪兽。'),
(73481154, 'Destroyer Golem', '破坏的石人', '破壊のゴーレム', 'Normal Monster', 'Rock', 'EARTH', 4, 1500, 1000, '巨大右臂为特征的石人，用右臂进行压迫攻击。'),
(80186010, 'Destroyersaurus', '嗜杀恐龙', 'キラーザウルス', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1800, 1100, '把这张卡从手卡丢弃去墓地。从卡组把1张「侏罗纪世界」加入手卡。'),
(18739764, 'Destruct Potion', '破坏疗药', 'デストラクト・ポーション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上存在的1只怪兽发动。选择的怪兽破坏，自己基本分回复破坏的怪兽的攻击力的数值。'),
(59235795, 'Destruction Cyclone', '死亡旋风', 'デスサイクロン', 'Effect Monster', 'Reptile', 'WIND', 7, 2000, 1500, '这张卡被战斗破坏送去墓地时，场上表侧表示存在的风属性怪兽以外的怪兽全部破坏。'),
(44373896, 'Destruction Dragon', '破坏龙', 'デストロイ・ドラゴン', 'Fusion Monster', 'Dragon', 'FIRE', 8, 2000, 3000, '这张卡在用「克里底亚之牙」的效果把自己的手卡·场上的「破坏轮」送去墓地的场合才能特殊召唤。 ①：1回合1次，以对方场上1张卡为对象才能发动。那张卡破坏。那之后，破坏的卡是怪兽卡的场合，给与对方那个原本攻击力数值的伤害。'),
(98956134, 'Destruction Jammer', '破坏干扰', 'デストラクション・ジャマー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '丢弃1张手卡。持有（把场上的怪兽破坏的效果）的卡的发动无效并破坏。'),
(62980542, 'Destruction of Destiny', '命运毁灭', 'デステニー・デストロイ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从自己卡组的最上面把3张卡送去墓地。这个效果送去墓地的魔法·陷阱卡每有1张，自己受到1000分伤害。'),
(5616412, 'Destruction Punch', '反击拳', 'カウンターパンチ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '被攻击的怪兽的守备力比对方攻击怪兽攻击力高的场合，伤害步骤结束后那个攻击的怪兽破坏。（伤害计算适用）'),
(21219755, 'Destruction Ring', '破坏指轮', '破壊指輪', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '破坏自己场上1只表侧表示的怪兽，双方各受1000点伤害。'),
(15155568, 'Destruction Sword Flash', '破坏剑一闪', '破壊剣一閃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有需以「破坏之剑士」为融合素材的融合怪兽存在的场合才能发动。对方场上的怪兽全部除外。 ②：以自己场上的「破坏之剑士」怪兽为对象的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个效果无效并破坏。'),
(32104431, 'Destruction Sword Memories', '破坏剑的追忆', '破壊剣の追憶', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡丢弃1张「破坏剑」卡才能发动。从卡组把1只「破坏之剑士」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。「龙破坏的剑士-破坏之剑士」决定的融合素材怪兽从自己墓地除外，把那1只融合怪兽从额外卡组融合召唤。'),
(41940225, 'Destruction Swordsman Fusion', '破坏剑士融合', '破壊剣士融合', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「破坏剑士融合」的①②的效果1回合各能使用1次。 ①：从自己手卡以及自己·对方场上把融合怪兽卡决定的融合素材怪兽送去墓地，把以「破坏之剑士」为融合素材的那1只融合怪兽从额外卡组融合召唤。 ②：这张卡在墓地存在的场合，把1张手卡送去墓地才能发动。墓地的这张卡加入手卡。'),
(30748475, 'Destructive Daruma Karma Cannon', '魔炮战机 达磨羯摩', '魔砲戦機ダルマ・カルマ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的怪兽全部变成里侧守备表示。那之后，场上有表侧表示怪兽存在的场合，那控制者必须把自身场上的表侧表示怪兽全部送去墓地。'),
(77859858, 'Destructive Draw', '步向破灭的速攻抽卡', '破滅へのクイック・ドロー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家在抽卡阶段开始时手卡是0张的场合，通常抽卡外可以再抽1张。这张卡的控制者在每次自己回合的结束阶段支付700基本分。这个时候基本分700未满的场合，基本分变成0。自己场上表侧表示存在的这张卡从场上离开时，自己受到3000分伤害。'),
(11232355, 'Destructotron', '超能破坏者', 'ディストラクター', 'Effect Monster', 'Psychic', 'EARTH', 4, 1600, 400, '支付1000基本分才能发动。选择对方场上盖放的1张魔法·陷阱卡破坏。此外，双方的结束阶段时，自己场上没有这张卡以外的念动力族怪兽存在的场合，这张卡破坏。'),
(5560911, 'Destrudo the Lost Dragon''s Frisson', '亡龙之战栗－死欲龙', '亡龍の戦慄－デストルドー', 'Tuner Monster', 'Dragon', 'DARK', 7, 1000, 3000, '这个卡名的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在的场合，把基本分支付一半，以自己场上1只6星以下的怪兽为对象才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡等级下降作为对象的怪兽的等级数值，从场上离开的场合回到卡组最下面。'),
(89086566, 'Detonate', '机雷化', '機雷化', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的「栗子球」以及「栗子球衍生物」全部破坏。那之后，选最多有和破坏数量相同数量的对方场上的卡破坏。'),
(24487411, 'Detonate Deleter', '雷管删除员', 'デトネイト・デリーター', 'Link Monster', 'Cyberse', 'DARK', NULL, 2100, NULL, '电子界族怪兽2只以上 ①：1回合1次，除连接3以上的连接怪兽外的表侧表示怪兽和这张卡进行战斗的伤害步骤开始时才能发动。那只怪兽破坏。 ②：1回合1次，把这张卡所连接区1只自己怪兽解放，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(46789706, 'Detonating Kuriboh', '机雷化的栗子球', '機雷化するクリボー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，场上有「栗子球」怪兽卡存在的场合才能发动。这张卡特殊召唤。 ②：对方把场上的怪兽的效果发动时才能发动。自己场上的这张卡当作持有以下效果的装备魔法卡使用给那只对方怪兽装备。 ●装备怪兽的效果无效化。'),
(41348446, 'Detonation Code', '爆破代码', 'デトネーション・コード', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「拓扑」连接怪兽存在的场合，以连接怪兽以外的自己墓地1只龙族·机械族·电子界族的暗属性怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡从魔法与陷阱区域除外的场合，下个回合的准备阶段才能发动。这张卡在自己场上盖放。'),
(20985997, 'Detonator Circle "A"', '破坏环-A', 'デストラクト・サークル－A', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把场上表侧表示存在的1只放置有A指示物的怪兽破坏，双方受到1000分伤害。'),
(85771021, 'Deus Token', '堕天使 阿斯蒙德斯', '堕天使アスモディウス', 'Token', 'Fairy', NULL, NULL, NULL, NULL, NULL),
(62587693, 'Deus X-Krawler', '机界降神 超机怪虫', '機怪神エクスクローラー', 'Flip Effect Monster', 'Insect', 'EARTH', 9, 2000, 3000, '这个卡名的③的效果1回合只能使用1次。 ①：里侧表示的这只怪兽为对象的魔法·陷阱·怪兽的效果由对方发动时，把这张卡变成表侧守备表示才能发动。那个发动无效并破坏。 ②：只要反转过的这张卡在怪兽区域存在，对方场上的怪兽发动的效果无效化。 ③：场上的这张卡被战斗·效果破坏的场合才能发动。和这张卡是原本的种族·属性不同的1只9星怪兽从卡组加入手卡。'),
(88176533, 'Devotee of Nephthys', '奈芙蒂斯的祭祀者', 'ネフティスの祀り手', 'Ritual Effect Monster', 'Spellcaster', 'WIND', 2, 1200, 1200, '「奈芙提斯的轮回」降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡仪式召唤成功的场合才能发动。从卡组把1只「奈芙提斯」怪兽特殊召唤。这个效果发动的回合的结束阶段这张卡破坏。 ②：这张卡在墓地存在的场合才能发动。选手卡1张「奈芙提斯」卡破坏，这张卡从墓地特殊召唤。'),
(30037118, 'Devouring Sarcoughagus', '死制棺 石棺', '死製棺サルコファガス', 'Effect Monster', 'Zombie', 'DARK', 4, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡被和对方怪兽的战斗破坏时才能发动。得到那只对方怪兽的控制权。那只怪兽变成不死族，攻击力·守备力变成0。 ②：这张卡在墓地存在的状态，自己的不死族怪兽被和对方怪兽的战斗破坏时，把这张卡除外才能发动。得到那只对方怪兽的控制权。那只怪兽变成不死族，攻击力·守备力变成0。'),
(90311614, 'Dewdark of the Ice Barrier', '冰结界的水影', '氷結界の水影', 'Tuner Monster', 'Aqua', 'WATER', 2, 1200, 800, '①：自己场上的表侧表示怪兽只有2星以下的怪兽的场合，这张卡可以直接攻击。'),
(70583986, 'Dewloren, Tiger King of the Ice Barrier', '冰结界之虎王 多楼兰', '氷結界の虎王 ドゥローレン', 'Synchro Monster', 'Beast', 'WATER', 6, 2000, 1400, '调整＋调整以外的水属性怪兽1只以上 这个卡名的效果1回合只能使用1次。 ①：以自己场上的其他的表侧表示卡任意数量为对象才能发动。那些自己的表侧表示卡回到手卡。这张卡的攻击力直到回合结束时上升这个效果回到手卡的卡数量×500。'),
(32302078, 'Dhampir Vampire Sheridan', '交血鬼－吸血鬼谢里丹', '交血鬼－ヴァンパイア・シェリダン', 'XYZ Monster', 'Zombie', 'DARK', 6, 2600, 1000, '6星怪兽×2只以上 把原本持有者是对方的怪兽作为这张卡的超量召唤的素材的场合，那些等级当作6星使用。 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1张卡为对象才能发动。那张卡送去墓地。 ②：1回合1次，场上的怪兽卡被效果送去对方墓地的场合或者被战斗破坏送去对方墓地的场合，把这张卡1个超量素材取除才能发动。那1只怪兽在自己场上守备表示特殊召唤。'),
(19327348, 'Dharc the Dark Charmer', '暗灵使 达尔克', '闇霊使いダルク', 'Flip Effect Monster', 'Spellcaster', 'DARK', 3, 500, 1500, '①：这张卡反转的场合，以对方场上1只暗属性怪兽为对象发动。这只怪兽表侧表示存在期间，得到那只怪兽的控制权。'),
(8264361, 'Dharc the Dark Charmer, Gloomy', '暗影之暗灵使 达尔克', '暗影の闇霊使いダルク', 'Link Monster', 'Spellcaster', 'DARK', NULL, 1850, NULL, '包含暗属性怪兽的怪兽2只 这个卡名在规则上也当作「凭依装着」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：以对方墓地1只暗属性怪兽为对象才能发动。那只怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：连接召唤的这张卡被战斗或者对方的效果破坏的场合才能发动。从卡组把1只守备力1500以下的暗属性怪兽加入手卡。'),
(96967123, 'Dharma Cannon', '大炮达摩', '大砲だるま', 'Normal Monster', 'Machine', 'DARK', 2, 900, 500, '堆满大炮的机械达磨。不会打偏。'),
(88757791, 'Dharma-Eye Magician', '法眼的魔术师', '法眼の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'LIGHT', 7, 2000, 2500, '①：只要这个回合灵摆召唤的这张卡在怪兽区域存在，自己场上的「魔术师」灵摆怪兽不会被对方的效果破坏。'),
(14307929, 'Diabell, Queen of the White Forest', '白森的妖魔 迪亚贝尔', '白き森の妖魔ディアベル', 'Synchro Monster', 'Illusion', 'LIGHT', 8, 2500, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用同调怪兽调整为素材作同调召唤的场合，以自己墓地1张魔法·陷阱卡为对象才能发动。那张卡加入手卡。 ②：对方把魔法·陷阱·怪兽的效果发动时，从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。自己的额外卡组·墓地·除外状态的1只7星以下的同调怪兽调整特殊召唤。'),
(72270339, 'Diabellstar the Black Witch', '黑魔女 迪亚贝尔斯塔', '黒魔女ディアベルスター', 'Effect Monster', 'Spellcaster', 'DARK', 7, 2500, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：这张卡可以把自己的手卡·场上1张卡送去墓地，从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「罪宝」魔法·陷阱卡在自己场上盖放。 ③：这张卡在对方回合从手卡·场上送去墓地的场合才能发动。从自己的手卡·场上把1张卡送去墓地，这张卡特殊召唤。'),
(23151193, 'Diabellstar Vengeance', '断罪之迪亚贝尔斯塔', '断罪のディアベルスター', 'Effect Monster', 'Fiend', 'DARK', 8, 2500, 2100, '这个卡名在规则上也当作「罪宝」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地把魔法卡和陷阱卡各1张除外才能发动。这张卡从手卡·墓地特殊召唤。 ②：自己·对方回合，把基本分支付一半，以对方场上1张卡为对象才能发动。那张卡破坏。那之后，场上有其他的「迪亚贝尔」怪兽卡存在的场合，可以从额外卡组把1只幻想魔族·魔法师族同调怪兽调整特殊召唤。'),
(53765052, 'Diabellze the Original Sinkeeper', '原罪的迪亚贝尔赛', '原罪のディアベルゼ', 'Effect Monster', 'Illusion', 'LIGHT', 7, 2500, 2000, '这个卡名的①的方法的特殊召唤1回合只能有1次，③的效果1回合只能使用1次。 ①：自己或对方的墓地有「罪宝」卡存在的场合，这张卡可以从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能把没有盖放的魔法·陷阱卡发动。 ③：这张卡在怪兽区域存在的状态，场上有魔法·陷阱卡被盖放的场合，以自己以及对方场上的卡各1张为对象才能发动。那些卡破坏。'),
(60145298, 'Diabellze the White Witch', '白魔女 迪亚贝尔赛', '白魔女ディアベルゼ', 'Effect Monster', 'Illusion', 'LIGHT', 8, 2500, 2100, '这个卡名在规则上也当作「白森林」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1张「罪宝」卡或「迪亚贝尔」卡送去墓地。 ③：只要自己场上有「迪亚贝尔」怪兽2只以上存在，自己场上的怪兽不会被对方的效果破坏。'),
(24634594, 'Diabolantis the Menacing Mantis', '魔螂 迪亚波兰提斯', '魔螂ディアボランティス', 'Synchro Monster', 'Insect', 'DARK', 8, 2500, 2200, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。把最多有那些作为同调素材的怪兽之内除调整以外的怪兽数量的昆虫族·植物族怪兽从卡组送去墓地。 ②：这张卡是已同调召唤的场合，以自己场上1只昆虫族·植物族怪兽为对象才能发动。那只怪兽直到回合结束时变成调整。'),
(11212437, 'Diabolic Dragon Fortress - Draluvice', '魔龙阁－德拉尔维斯', '魔竜閣－ドラルヴァイス', 'Normal Tuner Monster', 'Dragon', 'DARK', 7, 2300, 2500, '无休止地喷吐着龙之诅咒的女战士的末路。现在已经变为瘟疫的元凶，其形貌化为邪念旋绕的楼阁，就此成为人们所要复仇的对象。阻挡在自己眼前的讨伐队是过去被龙毁灭的村庄里的幸存者这种事，现今的她根本无从知晓…。'),
(78077209, 'Diabolica the Draconique General', '魔龙将 迪亚波利卡', '魔竜将ディアボリカ', 'Effect Monster', 'Fiend', 'DARK', 8, 2300, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡在手卡·墓地存在，「魔龙将 迪亚波利卡」以外的恶魔族怪兽被效果送去自己墓地的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡被效果送去墓地的场合，以「魔龙将 迪亚波利卡」以外的自己墓地1只恶魔族怪兽为对象才能发动。那只怪兽加入手卡。'),
(29424328, 'Diabolos, King of the Abyss', '魔王 迪亚波罗斯', '魔王ディアボロス', 'Effect Monster', 'Dragon', 'DARK', 7, 2800, 1000, '这张卡不能特殊召唤。这张卡上级召唤的场合，解放的怪兽必须是暗属性怪兽。 ①：这张卡只要在怪兽区域存在，不能用效果解放。 ②：对方抽卡阶段的抽卡前发动。把对方卡组最上面的卡确认，回到卡组最上面或者最下面。'),
(51644030, 'Diabound Kernel', '迪亚邦德之核', 'ディアバウンド・カーネル', 'Effect Monster', 'Fiend', 'DARK', 5, 1800, 1200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击宣言时发动。这张卡的攻击力上升600。 ②：以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时下降这张卡的攻击力数值。那之后，这张卡直到下个回合的准备阶段除外。这个效果在对方回合也能发动。'),
(6083904, 'Diabrocken of the Ghost Light', NULL, NULL, 'Effect Monster', 'Fiend', 'FIRE', 6, 2000, 2000, NULL),
(81994591, 'Diamond Core of Koa''ki Meiru', '核成兽的金刚核', 'コアキメイルの金剛核', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组把「核成兽的金刚核」以外的1张名字带有「核成」的卡加入手卡。此外，自己的主要阶段时把墓地的这张卡从游戏中除外才能发动。这个回合，自己场上的名字带有「核成」的怪兽不会被破坏。'),
(95169481, 'Diamond Dire Wolf', '恐牙狼 钻石恐狼', '恐牙狼 ダイヤウルフ', 'XYZ Monster', 'Beast', 'EARTH', 4, 2000, 1200, '4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己场上1只兽族·兽战士族·鸟兽族怪兽和场上1张卡为对象才能发动。那些卡破坏。'),
(98643358, 'Diamond Dust', '冰晶', 'ダイヤモンド・ダスト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上的水属性怪兽全部破坏。那之后，给与对方基本分这个效果破坏送去墓地的水属性怪兽数量×500的数值的伤害。'),
(96857854, 'Diamond Duston', '钻尘妖', 'ダイヤモンドダストン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的卡被战斗·效果破坏时才能发动。从卡组选那些破坏的卡数量的「尘妖」怪兽在自己·对方场上特殊召唤。 ②：这张卡在墓地存在的场合只有1次，把自己墓地1只「尘妖」怪兽除外才能发动。这张卡变成通常怪兽（恶魔族·暗·1星·攻0/守1000）在对方的怪兽区域守备表示特殊召唤（不当作陷阱卡使用）。这个效果特殊召唤的这张卡不能解放，也不能作为融合·同调·超量召唤的素材。'),
(19980975, 'Diamond-Dust Cyclone', '钻尘旋风', 'ダイヤモンドダスト・サイクロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择雾指示物放置有4个以上的1只怪兽发动。把选择怪兽破坏，破坏怪兽每放置有4个雾指示物，从自己卡组抽1张卡。'),
(84257640, 'Dian Keto the Cure Master', '治疗之神 迪安·凯特', '治療の神 ディアン・ケト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(17257342, 'Diana the Light Spirit', '光之精灵 狄安娜', '光の精霊 ディアーナ', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1700, 1000, '这张卡不能通常召唤。从自己墓地把1只光属性怪兽除外的场合可以特殊召唤。 ①：对方结束阶段发动。自己回复1000基本分。'),
(69893315, 'Dice Armadillo', '骰子犰狳', 'ダイス・アルマジロ', 'Normal Monster', 'Machine', 'EARTH', 5, 1650, 1800, '卷起身子就像骰子一样的犰狳。'),
(11808215, 'Dice Dungeon', '骰子地城', 'ダイス・ダンジョン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从卡组把1张「次元解骰」加入手卡。 ②：自己·对方的战斗阶段开始时才能发动。双方各自掷1次骰子，自身场上的全部怪兽的攻击力直到回合结束时受出现的数目的效果适用。 ●1：下降1000。 ●2：上升1000。 ●3：下降500。 ●4：上升500。 ●5：变成一半。 ●6：变成2倍。'),
(8868767, 'Dice It', '骰子减肥法', 'ダイスエット', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：掷1次骰子。发动回合的以下效果适用。 ●自己回合：从自己墓地选出现的数目数量的卡除外。出现的数目是1的场合，再从自己卡组上面把6张卡送去墓地。 ●对方回合：把出现的数目数量的卡从自己卡组上面送去墓地。出现的数目是6的场合，再选自己墓地1张卡除外。'),
(3549275, 'Dice Jar', '骰子壶', 'ダイス・ポット', 'Flip Effect Monster', 'Rock', 'LIGHT', 3, 200, 300, '反转：双方各自投掷1个骰子。投掷出来的数目比另一方低的玩家，受到（另一方投掷出的数目×500）的基本分的伤害。如果输给投掷出数目6的场合，输的玩家受到的是6000分的伤害。平局的场合再掷1次。'),
(83241722, 'Dice Re-Roll', '反转骰子', 'リバースダイス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，掷骰子的效果适用之际只有1次，可以重掷骰子。'),
(88482761, 'Dice Roll Battle', '掷骰战斗', 'ダイスロール・バトル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时以自己墓地1只「疾行机人」怪兽为对象才能发动。那只怪兽和手卡1只「疾行机人」调整除外，把持有和那2只的原本等级合计相同等级的1只同调怪兽从额外卡组特殊召唤。 ②：对方战斗步骤把墓地的这张卡除外，以自己以及对方场上的表侧攻击表示的同调怪兽各1只为对象才能发动。那只对方的表侧攻击表示怪兽向那只自己怪兽作出攻击，进行伤害计算。'),
(59905358, 'Dice Try!', '骰子冲击', 'ダイスインパクト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '对方发动的掷骰子效果的发动无效，那张卡破坏。'),
(31863912, 'Dice-nied', '指出出目', '出目出し', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方对怪兽的特殊召唤成功时，掷1次骰子。出现的数目和那特殊召唤的怪兽的等级相同的场合，那怪兽回到持有者手卡。'),
(93078761, 'Diced Dice', '从骰挑战', '賽挑戦', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：掷1次骰子，1·6出现的场合，把持有掷骰子效果的1张卡从卡组加入手卡。1·6以外出现的场合，再掷1次骰子，出现数目的以下效果适用。 ●1·6：场上的这张卡回到持有者手卡。 ●2～5：场上的这张卡回到持有者卡组最上面。'),
(62893810, 'Dicelops', '骰子独眼巨人', 'サイコロプス', 'Effect Monster', 'Machine', 'FIRE', 4, 1800, 200, '①：1回合1次，自己主要阶段才能发动。掷1次骰子，出现的数目的效果适用。 ●1：把对方手卡确认，从那之中选1张卡丢弃。 ●2～5：选自己1张手卡丢弃。 ●6：自己手卡全部丢弃。'),
(3493058, 'Dicephoon', '骰子旋风', 'サイコロン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：掷1次骰子，出现的数目的效果适用。 ●2·3·4：选场上1张魔法·陷阱卡破坏。 ●5：选场上2张魔法·陷阱卡破坏。 ●1·6：自己受到1000伤害。'),
(96015976, 'Diceversity', '再转', '再転', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，以场上1只持有和原本等级不同等级的怪兽为对象才能把这个效果发动。掷1次骰子。作为对象的怪兽的等级变成和出现的数目相同。'),
(66961194, 'Dictator of D.', '龙之主宰－龙的独裁者', 'ロード・オブ・ドラゴン－ドラゴンの独裁者－', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1200, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡·卡组把1只「青眼白龙」送去墓地才能发动。这张卡从手卡特殊召唤。 ②：从手卡丢弃1只「青眼白龙」或者1张有那个卡名记述的卡，以自己墓地1只「青眼」怪兽为对象才能发动。那只怪兽特殊召唤。 ③：只要自己场上有「青眼」怪兽存在，对方选择自身怪兽的攻击对象之际，那个攻击对象由自己选择。'),
(11961740, 'Different Dimension Capsule', '时光胶囊', 'タイムカプセル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从自己卡组选择1张卡，里侧表示从游戏中除外。发动后第2次的自己的准备阶段这张卡破坏，那张卡加入手卡。'),
(62437430, 'Different Dimension Deepsea Trench', '异次元海沟', '異次元海溝', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时，选自己的手卡·场上·墓地1只水属性怪兽从游戏中除外。那之后，场上表侧表示存在的这张卡被破坏时，这张卡的效果除外的怪兽在自己场上特殊召唤。'),
(50939127, 'Different Dimension Dragon', '异次元龙', '異次元竜 トワイライトゾーンドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 5, 1200, 1500, '这张卡不会被不指定对象的魔法、陷阱卡的效果破坏。这张卡不会被攻击力1900以下的怪兽战斗破坏。'),
(39900763, 'Different Dimension Encounter', '异次元的邂逅', '異次元の邂逅', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方有除外的自己怪兽1只以上存在的场合才能发动。双方玩家各自选除外的1只自己怪兽里侧守备表示特殊召唤。'),
(56460688, 'Different Dimension Gate', '异次元隔离机', '異次元隔離マシーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '从自己和对方场上各选择1只怪兽，从游戏中除外。这张卡被破坏并送去墓地时，被除外怪兽以相同的表示形式回到原本所在的场上。'),
(31849106, 'Different Dimension Ground', '异次元竞技场', '異次元グランド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合，被送去墓地的怪兽不去墓地而除外。'),
(87880531, 'Diffusion Wave-Motion', '扩散的波动', '拡散する波動', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方场上有怪兽存在的场合，支付1000基本分，以自己场上1只7星以上的魔法师族怪兽为对象才能发动。这个回合，那只怪兽以外的怪兽不能攻击，作为对象的怪兽必须尽可能向对方怪兽全部各作1次攻击。那些攻击破坏的怪兽的效果不能发动并无效化。'),
(29948642, 'Dig Beak', '鸟嘴兽', 'ディッグ・ビーク', 'Normal Monster', 'Beast', 'EARTH', 2, 500, 800, '卷起蛇一样长的身体，一边回转一边用嘴攻击。'),
(81782376, 'Dig of Destiny', '命运之发掘', '運命の発掘', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己受到战斗伤害时才能发动。自己从卡组抽1张。 ②：场上的这张卡被对方的效果破坏的场合才能发动。自己从卡组抽出自己墓地的「命运之发掘」的数量。'),
(300302004, 'Digging for Gold', NULL, NULL, 'Skill Card', 'David', NULL, NULL, NULL, NULL, NULL),
(49658464, 'Digit Jamming', '无千干扰', '無千ジャミング', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：场上有攻击力1000以上的怪兽存在的场合，怪兽进行战斗的伤害计算时发动。场上的全部怪兽攻击力变成那自身攻击力每有1000则降1000的数值，守备力变成那自身守备力每有1000则降1000的数值。 ②：这张卡被破坏的场合发动。场上的全部怪兽直到回合结束时攻击力变成那自身攻击力每有1000则降1000的数值，守备力变成那自身守备力每有1000则降1000的数值。'),
(68950538, 'Digital Bug Centibit', '电子光虫-比特蜈蚣', '電子光虫－センチビット', 'Effect Monster', 'Insect', 'LIGHT', 3, 1500, 500, '把这张卡作为超量召唤的素材的场合，不是昆虫族怪兽的超量召唤不能使用。 ①：1回合1次，表侧攻击表示的这张卡变成守备表示时才能发动。从卡组把1只昆虫族·3星怪兽守备表示特殊召唤。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡可以向对方场上的全部守备表示怪兽各作1次攻击。'),
(32465539, 'Digital Bug Cocoondenser', '电子光虫-电容茧', '電子光虫－コクーンデンサ', 'Effect Monster', 'Insect', 'LIGHT', 3, NULL, 2000, '把这张卡作为超量召唤的素材的场合，不是昆虫族怪兽的超量召唤不能使用。 ①：1回合1次，这张卡在场上攻击表示存在的场合，以自己墓地1只昆虫族·3星怪兽为对象才能发动。这张卡变成守备表示，作为对象的怪兽守备表示特殊召唤。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡向守备表示怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(58600555, 'Digital Bug Corebage', '电子光虫-核心菜粉蝶', '電子光虫－コアベージ', 'XYZ Monster', 'Insect', 'LIGHT', 5, 2200, 1800, '昆虫族·光属性5星怪兽×2只以上 这张卡也能从自己场上的3·4阶的昆虫族超量怪兽把2个超量素材取除，在那只超量怪兽上面重叠来超量召唤。 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只守备表示怪兽为对象才能发动。那只怪兽回到持有者卡组。 ②：1回合1次，场上的怪兽的表示形式变更的场合才能发动。选自己墓地1只昆虫族怪兽在这张卡下面重叠作为超量素材。'),
(83048208, 'Digital Bug LEDybug', '电子光虫-LED瓢虫', '電子光虫－LEDバグ', 'Effect Monster', 'Insect', 'LIGHT', 3, 500, NULL, '把这张卡作为超量召唤的素材的场合，不是昆虫族怪兽的超量召唤不能使用。 ①：1回合1次，表侧攻击表示的这张卡变成守备表示时才能发动。从卡组把1只昆虫族·3星怪兽加入手卡。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡战斗破坏怪兽时自己从卡组抽1张。'),
(19301729, 'Digital Bug Registrider', '电子光虫-电阻水黾', '電子光虫－レジストライダー', 'Effect Monster', 'Insect', 'LIGHT', 3, 1000, 1000, '把这张卡作为超量召唤的素材的场合，不是昆虫族怪兽的超量召唤不能使用。 ①：自己对昆虫族·3星怪兽的召唤成功时才能发动。这张卡从手卡特殊召唤。那之后，可以把这张卡和那只怪兽的等级变成5星或者7星。 ②：这张卡从手卡的特殊召唤成功的场合才能发动。选自己场上1只昆虫族怪兽把表示形式变更。 ③：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡的攻击力·守备力上升1000。'),
(85004150, 'Digital Bug Rhinosebus', '电子光虫-总线独角仙', '電子光虫－ライノセバス', 'XYZ Monster', 'Insect', 'LIGHT', 7, 2600, 2200, '昆虫族·光属性7星怪兽×2只以上 这张卡也能从自己场上的5·6阶的昆虫族超量怪兽把2个超量素材取除，在那只超量怪兽上面重叠来超量召唤。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：1回合1次，把这张卡1个超量素材取除才能发动。对方场上的守备力最高的怪兽破坏。这个效果在对方回合也能发动。'),
(12615446, 'Digital Bug Scaradiator', '电子光虫-散热器蜣螂', '電子光虫－スカラジエータ', 'XYZ Monster', 'Insect', 'LIGHT', 3, 1800, 1400, '昆虫族·光属性3星怪兽×2只以上 ①：1回合1次，把这张卡2个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽的表示形式变更，那个效果直到回合结束时无效。这个效果在对方回合也能发动。 ②：1回合1次，这张卡战斗破坏对方怪兽送去墓地时才能发动。破坏的那只怪兽在这张卡下面重叠作为超量素材。'),
(94344242, 'Digital Bug Websolder', '电子光虫-焊料织网蛛', '電子光虫－ウェブソルダー', 'Effect Monster', 'Insect', 'LIGHT', 3, 500, 1500, '把这张卡作为超量召唤的素材的场合，不是昆虫族怪兽的超量召唤不能使用。 ①：1回合1次，以自己场上1只表侧攻击表示怪兽为对象才能发动。那只怪兽变成守备表示，从手卡把1只昆虫族·3星怪兽守备表示特殊召唤。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这次超量召唤成功的场合发动。对方场上的全部表侧表示怪兽守备力变成0，变成守备表示。'),
(32295838, 'Digitron', '数码创机', 'デジトロン', 'Normal Monster', 'Cyberse', 'EARTH', 2, 1500, NULL, '电子空间发现的亚种。它的信息量好像稍多点。'),
(29515122, 'Digvorzhak, King of Heavy Industry', '重机王 土木·夏克', '重機王ドボク・ザーク', 'XYZ Monster', 'Machine', 'EARTH', 5, 3200, 2000, '5星怪兽×3 1回合1次，把这张卡1个超量素材取除才能发动。从对方卡组上面把3张卡送去墓地。这个效果送去墓地的卡之中有怪兽卡的场合，把最多有那个数量的对方场上的卡破坏。'),
(23732205, 'Dillingerous Dragon', '德林加险龙', 'デリンジャラス・ドラゴン', 'Link Monster', 'Dragon', 'DARK', NULL, 1600, NULL, '龙族·暗属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：对方结束阶段，以这个回合没有攻击宣言的对方场上1只攻击表示怪兽为对象才能发动。那只怪兽破坏，给与对方那个原本攻击力数值的伤害。 ②：这张卡在墓地存在的状态，自己场上有「弹丸」怪兽特殊召唤的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(77683371, 'Dimension Conjurer', '次元施法者', 'ディメンション・コンジュラー', 'Effect Monster', 'Spellcaster', 'DARK', 1, 500, 500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从自己的卡组·墓地选1张「次元魔法」加入手卡。 ②：这张卡从怪兽区域送去墓地的场合才能发动。自己从卡组抽出自己场上的魔法师族怪兽的数量。那之后，选抽出数量的手卡用喜欢的顺序回到卡组上面。'),
(47292920, 'Dimension Dice', '次元解骰', 'ディメンジョン・ダイス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：持有掷骰子效果的卡在自己场上存在的场合，把自己场上1只怪兽解放才能发动。把持有掷骰子的怪兽效果的1只怪兽从手卡·卡组特殊召唤。'),
(95194279, 'Dimension Distortion', '次元歪曲', '次元の歪み', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '当自己的墓地里没有卡存在的场合这张卡才能发动。选择自己1只被除外的怪兽特殊召唤到自己场上。'),
(1896112, 'Dimension Explosion', '次元诱爆', '次元誘爆', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只融合怪兽回到融合卡组才能发动。双方选择从游戏中除外的怪兽最多2只，在各自场上特殊召唤。'),
(1596508, 'Dimension Fortress Weapon', '次元要塞兵器', '次元要塞兵器', 'Effect Monster', 'Machine', 'DARK', 4, 1700, 200, '只要这张卡在场上表侧表示存在，双方不能从卡组把卡送去墓地。'),
(23557835, 'Dimension Fusion', '次元融合', '次元融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '支付2000基本分。双方将各自被除外的怪兽尽可能特殊召唤上场。'),
(89190953, 'Dimension Fusion Destruction', '次元融合杀', '次元融合殺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上·墓地把「幻魔」融合怪兽卡决定的融合素材怪兽除外，把那1只融合怪兽从额外卡组无视召唤条件特殊召唤。这个效果特殊召唤的怪兽的战斗发生的对自己的战斗伤害变成0。自己场上有「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中任意种存在的场合，对方不能对应这张卡的发动把效果发动。'),
(44046281, 'Dimension Gate', '次元之门', 'ディメンション・ゲート', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的发动时，选择自己场上1只怪兽表侧表示从游戏中除外。此外，对方怪兽的直接攻击宣言时，可以把场上表侧表示存在的这张卡送去墓地。这张卡被送去墓地的场合，可以把这张卡的效果除外的怪兽特殊召唤。'),
(54175023, 'Dimension Guardian', '次元守护者', 'ディメンション・ガーディアン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以自己场上1只表侧攻击表示怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，那只怪兽不会被战斗·效果破坏。那只怪兽从场上离开的场合这张卡破坏。'),
(73414375, 'Dimension Jar', '次元壶', 'ディメンション・ポッド', 'Flip Effect Monster', 'Machine', 'DARK', 2, 200, 200, '反转：双方均可以从对方墓地中选至多3张卡从游戏中除外。'),
(80560728, 'Dimension Mirage', '次元海市蜃楼', 'ディメンション・ミラージュ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以对方场上1只表侧攻击表示怪兽为对象才能把这张卡发动。 ①：作为对象的怪兽的攻击没让攻击对象怪兽被破坏的伤害步骤结束时，把自己墓地1只怪兽除外才能把这个效果发动。作为对象的怪兽变成再1次可以攻击，必须继续攻击。 ②：作为对象的怪兽从场上离开的场合这张卡破坏。'),
(54297661, 'Dimension Reflector', '次元反射镜', 'ディメンション・リフレクター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：把自己场上2只怪兽除外，以对方场上1只表侧表示怪兽为对象才能把这张卡发动。这张卡发动后变成持有和作为对象的怪兽的攻击力相同数值的攻击力·守备力的效果怪兽（魔法师族·暗·4星·攻/守?）在怪兽区域攻击表示特殊召唤。这张卡也当作陷阱卡使用。 ②：这张卡的效果让这张卡特殊召唤成功的场合发动。给与对方这张卡的攻击力数值的伤害。'),
(91800273, 'Dimension Shifter', '次元吸引者', 'ディメンション・アトラクター', 'Effect Monster', 'Spellcaster', 'DARK', 6, 1200, 2200, '①：自己·对方回合，自己墓地没有卡存在的场合，把这张卡从手卡送去墓地才能发动。直到下个回合的结束时，被送去墓地的卡不去墓地而除外。'),
(73632127, 'Dimension Slice', '次元崩落', 'ディメンション・スライド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有怪兽特殊召唤时才能发动。选择对方场上表侧表示存在的1只怪兽从游戏中除外。那次特殊召唤是超量召唤的场合，这张卡可以在盖放的回合发动。'),
(17787975, 'Dimension Sphinx', '次元斯芬克斯', 'ディメンション・スフィンクス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以自己场上1只表侧攻击表示怪兽为对象才能把这张卡发动。 ①：作为对象的怪兽被比那只怪兽攻击力高的对方怪兽攻击的战斗步骤中1次，可以把这个效果发动。给与对方那只攻击怪兽和作为对象的怪兽的攻击力差的数值的伤害。 ②：作为对象的怪兽从场上离开的场合这张卡破坏。'),
(67095270, 'Dimension Wall', '次元壁', 'ディメンション・ウォール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。这次战斗让自己受到的战斗伤害，作为代替由对方承受。'),
(62107612, 'Dimension Wanderer', '次元流浪士', 'ディメンション・ワンダラー', 'Effect Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '「银河眼光子龙」的效果让怪兽从游戏中除外时，把这张卡从手卡送去墓地才能发动。给与对方基本分3000分伤害。「次元流浪士」的效果1回合只能使用1次。'),
(36733451, 'Dimensional Alchemist', '次元合成师', '次元合成師', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1300, 200, '①：1回合1次，自己主要阶段才能发动。自己卡组最上面的卡除外，这张卡的攻击力直到回合结束时上升500。 ②：自己场上的这张卡被破坏送去墓地时，以除外的1只自己怪兽为对象才能发动。那只怪兽加入手卡。'),
(52254878, 'Dimensional Allotrope Varis', '次元同异体 多变人', '次元同異体ヴァリス', 'Tuner Monster', 'Psychic', 'LIGHT', 1, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡不会被和与这张卡种族或者属性相同的怪兽的战斗破坏。 ②：宣言种族和属性各1个才能发动。这张卡直到对方回合结束时变成宣言的种族·属性。'),
(83326048, 'Dimensional Barrier', '次元障壁', '次元障壁', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：宣言1个怪兽的种类（仪式·融合·同调·超量·灵摆）才能发动。这个回合中，以下效果适用。 ●双方不能把宣言的种类的怪兽特殊召唤，场上的宣言种类的怪兽的效果无效化。'),
(81674782, 'Dimensional Fissure', '次元的裂缝', '次元の裂け目', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，被送去墓地的怪兽不去墓地而除外。'),
(98666339, 'Dimensional Inversion', '反转次元', 'リバースディメンション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '原本的持有者是自己的怪兽被对方的效果从游戏中除外时才能发动。那1只怪兽在自己场上特殊召唤。'),
(70342110, 'Dimensional Prison', '次元幽禁', '次元幽閉', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时，选择1只攻击怪兽才能发动。选择的攻击怪兽从游戏中除外。'),
(22959079, 'Dimensionhole', '虫洞', 'ワーム・ホール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选自己场上的1只怪兽，在自己的下次的准备阶段之前除外。除外的时候，被选择的怪兽的怪兽区的位置不能使用。'),
(90965652, 'Dimer Synthesis', '二量合成', '二量合成', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：可以从以下效果选择1个发动。 ●从卡组把1张「化合电界」加入手卡。 ●从卡组把1张「完全燃烧」和1只「化合兽」怪兽加入手卡。 ②：把墓地的这张卡除外，以包含再1次召唤状态的二重怪兽的自己场上2只表侧表示怪兽为对象才能发动。直到回合结束时，作为对象的1只怪兽的攻击力变成0，并由另1只怪兽的攻击力上升那个原本攻击力数值。'),
(30432463, 'Dimonno Vaalmonica', '魔鬼之声・华耳琴璃', '悪魔の聲', 'Pendulum Effect Monster', 'Fiend', 'LIGHT', 4, 1200, 2100, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从手卡丢弃1张其他卡才能发动。从卡组选1只「天使之声」，这张卡和那张卡在自己的灵摆区域放置。 ②：这张卡召唤·特殊召唤的回合的自己主要阶段，从自己墓地把1张「异响鸣」通常魔法·通常陷阱卡除外才能发动。那张魔法·陷阱卡发动时的受到伤害的选项的效果适用。'),
(93854893, 'Dingirsu, the Orcust of the Evening Star', '宵星之自鸣天琴 丁吉尔苏', '宵星の機神ディンギルス', 'XYZ Monster', 'Machine', 'DARK', 8, 2600, 2100, '8星怪兽×2 自己对「宵星之机神 丁吉尔苏」1回合只能有1次特殊召唤，这张卡也能在自己场上的「自奏圣乐」连接怪兽上面重叠来超量召唤。 ①：这张卡特殊召唤的场合，可以从以下效果选择1个发动。 ●对方场上1张卡送去墓地。 ●把自己的除外状态的1只机械族怪兽作为这张卡的超量素材。 ②：自己场上的卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(300104003, 'Dino Destruction', NULL, NULL, 'Skill Card', 'Rex', NULL, NULL, NULL, NULL, NULL),
(27143874, 'Dino-Sewing', '缝制恐龙', 'ダイナソーイング', 'Effect Monster', 'Fiend', 'EARTH', 4, NULL, NULL, '①：这张卡不会被战斗破坏。 ②：这张卡被选择作为攻击对象的场合发动。这张卡的攻击力·守备力上升1000。 ③：这张卡攻击的伤害计算后发动。这张卡的②的效果上升的数值回到0。'),
(41128647, 'Dinomic Powerload', '机动阵 强化', 'ダイナミックP', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的「雾动机龙」怪兽的攻击力·守备力上升300。 ②：自己的「雾动机龙」怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(58984738, 'Dinomight Knight, the True Dracofighter', '真龙拳士 机动重装 铁拳', '真竜拳士ダイナマイトK', 'Effect Monster', 'Wyrm', 'WATER', 6, 2500, 1200, '这张卡表侧表示上级召唤的场合，可以作为怪兽的代替而把自己场上的永续魔法·永续陷阱卡解放。 ①：这张卡是已上级召唤的场合，1回合1次，对方把魔法·陷阱·怪兽的效果发动时才能发动。从卡组选1张「真龙」永续陷阱卡加入手卡或在自己场上发动。'),
(28720123, 'Dinomight Powerload, the Dracoslayer', '龙剑士 机动重装 强化', '竜剣士ダイナマイトP', 'Pendulum Effect Monster', 'Machine', 'WATER', 4, 1700, 1800, '这个卡名在规则上也当作「雾动机龙」卡使用。这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡被解放的场合才能发动。除「龙剑士 雾动轰·输力」外的1只「龙剑士」灵摆怪兽或「雾动机龙」灵摆怪兽从自己的额外卡组（表侧）加入手卡。'),
(32134638, 'Dinomist Ankylos', '机动雾龙・甲龙', 'ダイナミスト・アンキロス', 'Pendulum Effect Monster', 'Machine', 'WATER', 4, 1500, 2000, '①：只要这张卡在怪兽区域存在，自己的「雾动机龙」怪兽战斗破坏的怪兽除外。'),
(368382, 'Dinomist Brachion', '机动雾龙・腕龙', 'ダイナミスト・ブラキオン', 'Pendulum Effect Monster', 'Machine', 'WATER', 5, 2000, 800, '①：自己的怪兽区域没有「雾动机龙·腕龙」存在，场上的攻击力最高的怪兽在对方场上存在的场合，这张卡可以从手卡特殊召唤。'),
(37752990, 'Dinomist Ceratops', '机动雾龙・角龙', 'ダイナミスト・ケラトプス', 'Pendulum Effect Monster', 'Machine', 'WATER', 5, 2100, 400, '①：自己场上的怪兽只有「雾动机龙·角龙」以外的「雾动机龙」怪兽的场合，这张卡可以从手卡特殊召唤。'),
(77116346, 'Dinomist Charge', '机动雾龙・充能', 'ダイナミスト・チャージ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「雾动机龙充能」在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，从卡组把1只「雾动机龙」怪兽加入手卡。 ②：1回合1次，「雾动机龙」卡从场上表侧表示加入自己的额外卡组的场合发动。那1张卡加入手卡。'),
(74582050, 'Dinomist Eruption', '机动雾龙・喷发', 'ダイナミスト・エラプション', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的「雾动机龙」怪兽被战斗·效果破坏的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(38988538, 'Dinomist Plesios', '机动雾龙・蛇颈龙', 'ダイナミスト・プレシオス', 'Pendulum Effect Monster', 'Machine', 'WATER', 4, 1700, 1400, '①：只要这张卡在怪兽区域存在，对方场上的怪兽的攻击力·守备力下降自己场上的「雾动机龙」卡数量×100。'),
(64973287, 'Dinomist Pteran', '机动雾龙・无齿翼龙', 'ダイナミスト・プテラン', 'Pendulum Effect Monster', 'Machine', 'WATER', 4, 1800, 1200, '①：这张卡战斗破坏对方怪兽时才能发动。从卡组把1张「雾动机龙」卡加入手卡。'),
(63251695, 'Dinomist Rex', '机动雾龙・暴龙', 'ダイナミスト・レックス', 'Pendulum Effect Monster', 'Machine', 'WATER', 5, 2400, 2200, '①：这张卡进行攻击的伤害步骤结束时，可以把这张卡以外的自己场上1只「雾动机龙」怪兽解放，从以下效果选择1个发动。 ●这张卡向对方怪兽可以继续攻击，向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ●选对方的手卡·场上1张卡回到持有者卡组（从手卡选的场合是随机选）。那之后，这张卡的攻击力上升100。'),
(41554273, 'Dinomist Rush', '机动雾龙・突击', 'ダイナミスト・ラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「雾动机龙突进」在1回合只能发动1张。 ①：从卡组把1只「雾动机龙」怪兽特殊召唤。这个效果特殊召唤的怪兽不受其他卡的效果影响，结束阶段破坏。'),
(5067884, 'Dinomist Spinos', '机动雾龙・棘龙', 'ダイナミスト・スピノス', 'Pendulum Effect Monster', 'Machine', 'WATER', 5, 2500, 1800, '①：可以把这张卡以外的自己场上1只「雾动机龙」怪兽解放，从以下效果选择1个发动。 ●这个回合，这张卡可以直接攻击。 ●这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(1580833, 'Dinomist Stegosaur', '机动雾龙・剑龙', 'ダイナミスト・ステゴサウラー', 'Pendulum Effect Monster', 'Machine', 'WATER', 4, 1600, 1800, '①：这张卡以外的自己的灵摆怪兽和对方怪兽进行战斗的伤害计算后才能发动。那些进行战斗的双方怪兽破坏。'),
(60675348, 'Dinomists Howling', '机动雾龙・咆哮', 'ダイナミスト・ハウリング', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，可以从卡组选最多2只「雾动机龙」灵摆怪兽在自己的灵摆区域放置。放置的场合，直到下个回合的结束时，自己不是「雾动机龙」怪兽不能灵摆召唤。 ②：这张卡已在魔法与陷阱区域表侧表示存在的场合，1回合1次，把自己场上1只「雾动机龙」怪兽解放，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。'),
(52020510, 'Dinomorphia Alert', '恐啡肽骇龙・警报', 'ダイノルフィア・アラート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把基本分支付一半才能发动。等级合计最多到8星以下为止，从自己墓地选最多2只「恐啡肽狂龙」怪兽特殊召唤。这个回合，自己不是「恐啡肽狂龙」怪兽不能特殊召唤，不能用由这个效果特殊召唤的怪兽攻击宣言。 ②：自己基本分是2000以下，对方把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。这个回合，对方的效果发生的对自己的效果伤害变成0。'),
(99414629, 'Dinomorphia Brute', '恐啡肽骇龙・暴虐', 'ダイノルフィア・ブルート', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把基本分支付一半才能发动。选自己场上1只「恐啡肽狂龙」怪兽和对方场上1张卡破坏。 ②：自己基本分是2000以下，对方把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。这个回合，对方的效果发生的对自己的效果伤害变成0。'),
(38628859, 'Dinomorphia Diplos', '恐啡肽骇龙・迪普梁斯', 'ダイノルフィア・ディプロス', 'Effect Monster', 'Dinosaur', 'DARK', 4, 1000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「恐啡肽狂龙」卡送去墓地。自己基本分是2000以下的场合，再给与对方500伤害。 ②：这张卡被战斗·效果破坏的场合，从自己墓地把1张陷阱卡除外才能发动。从自己墓地选「恐啡肽狂龙·梁龙」以外的1只4星以下的「恐啡肽狂龙」怪兽特殊召唤。'),
(26631975, 'Dinomorphia Domain', '恐啡肽骇龙・领域', 'ダイノルフィア・ドメイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段，把基本分支付一半才能发动。从自己的手卡·卡组·场上把「恐啡肽狂龙」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：自己基本分是2000以下，对方把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。这个回合，对方的效果发生的对自己的效果伤害变成0。'),
(78420796, 'Dinomorphia Frenzy', '恐啡肽骇龙・狂乱', 'ダイノルフィア・フレンジー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方主要阶段，把基本分支付一半才能发动。「恐啡肽狂龙」融合怪兽卡决定的融合素材怪兽从卡组以及额外卡组各1只送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：自己基本分是2000以下，对方把魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。这个回合，对方的效果发生的对自己的效果伤害变成0。'),
(7336745, 'Dinomorphia Intact', '恐啡肽骇龙・无损', 'ダイノルフィア・インタクト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「恐啡肽狂龙」卡存在，怪兽的效果发动时，把基本分支付一半才能发动。那个发动无效并破坏。这个回合，自己受到的战斗伤害变成那个时候的自己基本分一半的数值。 ②：自己基本分是2000以下，自己要受到战斗伤害的伤害计算时，把墓地的这张卡除外才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(48832775, 'Dinomorphia Kentregina', '恐啡肽骇龙・肯特莱钉娜', 'ダイノルフィア・ケントレギナ', 'Fusion Monster', 'Dinosaur', 'DARK', 6, 4000, NULL, '卡名不同的「恐啡肽狂龙」怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力下降自己基本分数值。 ②：自己·对方的主要阶段，把基本分支付一半，从自己墓地把1张「恐啡肽狂龙」通常陷阱卡除外才能发动。这个效果变成和那张陷阱卡发动时的效果相同。 ③：这张卡被战斗·效果破坏的场合才能发动。从自己墓地选1只4星以下的「恐啡肽狂龙」怪兽特殊召唤。'),
(28292031, 'Dinomorphia Reversion', '恐啡肽骇龙・逆转', 'ダイノルフィア・リヴァージョン', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「恐啡肽狂龙」融合怪兽存在的场合，把基本分支付一半，从自己墓地把1张反击陷阱卡除外才能发动。这个效果变成和那张反击陷阱卡发动时的效果相同。 ②：自己基本分是2000以下，自己要受到战斗伤害的伤害计算时，把墓地的这张卡除外才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(92798873, 'Dinomorphia Rexterm', '恐啡肽骇龙・终结暴龙', 'ダイノルフィア・レクスターム', 'Fusion Monster', 'Dinosaur', 'DARK', 8, 3000, NULL, '「恐啡肽狂龙」融合怪兽＋「恐啡肽狂龙」怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：持有自己基本分数值以上的攻击力的对方场上的怪兽不能把效果发动。 ②：自己·对方回合，把基本分支付一半才能发动。对方场上的全部怪兽的攻击力直到回合结束时变成和自己基本分数值相同。 ③：这张卡被战斗·效果破坏的场合才能发动。从自己墓地选1只6星以下的「恐啡肽狂龙」怪兽特殊召唤。'),
(25419323, 'Dinomorphia Shell', '恐啡肽骇龙・甲壳', 'ダイノルフィア・シェル', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方战斗阶段开始时，把基本分支付一半才能发动。在自己场上把1只「恐啡肽狂龙衍生物」（恐龙族·暗·10星·攻0/守3000）特殊召唤。这个回合，只要这个效果特殊召唤的衍生物在自己场上存在，对方不能选择其他怪兽作为攻击对象。 ②：自己基本分是2000以下，自己要受到战斗伤害的伤害计算时，把墓地的这张卡除外才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(52807032, 'Dinomorphia Sonic', '恐啡肽骇龙・音速', 'ダイノルフィア・ソニック', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「恐啡肽狂龙」怪兽存在，对方把魔法·陷阱卡发动时，把基本分支付一半才能发动。那个发动无效并破坏。那之后，选自己场上1只「恐啡肽狂龙」怪兽破坏。 ②：自己基本分是2000以下，自己要受到战斗伤害的伤害计算时，把墓地的这张卡除外才能发动。那次战斗发生的对自己的战斗伤害变成0。'),
(74936480, 'Dinomorphia Stealthbergia', '恐啡肽骇龙・隐形翼龙', 'ダイノルフィア・ステルスベギア', 'Fusion Monster', 'Dinosaur', 'DARK', 6, NULL, 2500, '卡名不同的「恐啡肽狂龙」怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：只要自己基本分是2000以下，自己为让「恐啡肽狂龙」怪兽的效果以及陷阱卡发动而支付的基本分变成不需要。 ②：对方把怪兽的效果发动时才能发动。给与对方那只怪兽的原本攻击力数值的伤害。 ③：这张卡被战斗·效果破坏的场合才能发动。从自己墓地选1只4星以下的「恐啡肽狂龙」怪兽特殊召唤。'),
(92133240, 'Dinomorphia Therizia', '恐啡肽骇龙・特镰西娅', 'ダイノルフィア・テリジア', 'Effect Monster', 'Dinosaur', 'DARK', 4, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组选1张「恐啡肽狂龙」陷阱卡在自己的魔法与陷阱区域盖放。自己基本分是2000以下的场合，再让这张卡的攻击力上升500。 ②：这张卡被战斗·效果破坏的场合，从自己墓地把1张陷阱卡除外才能发动。从自己墓地选「恐啡肽狂龙·镰刀龙」以外的1只4星以下的「恐啡肽狂龙」怪兽特殊召唤。'),
(300203001, 'Dinosaur Kingdom', NULL, NULL, 'Skill Card', 'Rex', NULL, NULL, NULL, NULL, NULL),
(22638495, 'Dinoster Power, the Mighty Dracoslayer', '刚龙剑士 机动行者 强劲', '剛竜剣士ダイナスターP', 'Fusion Monster', 'Dragon', 'WATER', 8, 2000, 2950, '「龙剑士」灵摆怪兽＋灵摆怪兽 把自己场上的上记卡解放的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：只要这张卡在怪兽区域存在，自己的怪兽区域·灵摆区域的灵摆怪兽卡不会被战斗以及对方的效果破坏。 ②：1回合1次，自己主要阶段才能发动。从自己的手卡·墓地选1只「龙剑士」灵摆怪兽特殊召唤。这个效果特殊召唤的怪兽不能作为融合素材。'),
(84631951, 'Dinovatus Docus', '新世侵略梁龙', 'ディノベーダー・ドクス', 'Effect Monster', 'Dinosaur', 'EARTH', 6, 1500, 2200, '自己对「恐龙侵略者·双梁龙」1回合只能有1次特殊召唤，那个②的效果1回合只能使用1次。 ①：自己场上有恐龙族怪兽2只以上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：把自己场上1只4星以下的怪兽解放才能发动。比解放的怪兽等级高2星或低2星的1只恐龙族怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(93507434, 'Dinowrestler Capaptera', '恐龙摔跤手・卡帕扑翼龙', 'ダイナレスラー・カパプテラ', 'Effect Monster', 'Dinosaur', 'WIND', 3, 1600, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，以对方场上1只怪兽为对象才能发动。那只怪兽送去墓地。 ②：这张卡作为「恐龙摔跤手」连接怪兽的连接素材送去墓地的场合才能发动。那只连接怪兽的攻击力直到回合结束时上升1000。'),
(29996433, 'Dinowrestler Capoeiraptor', '恐龙摔跤手・卡波耶拉伶盗龙', 'ダイナレスラー・カポエラプトル', 'Effect Monster', 'Dinosaur', 'EARTH', 4, 1800, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：攻击表示的这张卡不会被战斗破坏，被对方怪兽攻击的伤害步骤结束时这张卡变成守备表示。 ②：这张卡在怪兽区域守备表示存在的场合，自己·对方的准备阶段才能发动。从卡组把1只「恐龙摔跤手·卡波耶拉盗龙」特殊召唤。'),
(22900219, 'Dinowrestler Chimera T Wrextle', '恐龙摔跤手・奇美拉・角力暴龙', 'ダイナレスラー・キメラ・Tレッスル', 'Fusion Monster', 'Dinosaur', 'EARTH', 8, 3500, NULL, '「恐龙摔跤手」连接怪兽＋「恐龙摔跤手」怪兽 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：对方不能选择其他怪兽作为攻击对象。 ④：这张卡战斗破坏怪兽的场合发动。这张卡的攻击力上升500。 ⑤：这张卡被效果破坏的场合发动。对方的攻击表示怪兽全部破坏。'),
(75366958, 'Dinowrestler Coelasilat', '恐龙摔跤手・班卡西拉腔骨龙', 'ダイナレスラー・コエロフィシラット', 'Tuner Monster', 'Dinosaur', 'EARTH', 2, 100, 800, '这个卡名的①的方法的特殊召唤在决斗中只能有1次。 ①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。把这个方法特殊召唤的这张卡作为连接召唤的素材的场合，不是「恐龙摔跤手」怪兽的连接召唤不能使用。'),
(48372950, 'Dinowrestler Eskrimamenchi', '恐龙摔跤手・短棍马门溪龙', 'ダイナレスラー・エスクリマメンチ', 'Effect Monster', 'Dinosaur', 'EARTH', 6, 2200, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有「恐龙摔跤手」怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡在墓地存在，自己回合对方对怪兽的特殊召唤成功的场合，以自己墓地1只4星以下的「恐龙摔跤手」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，墓地的这张卡加入手卡。'),
(58672736, 'Dinowrestler Giga Spinosavate', '恐龙摔跤手・吉咖・萨瓦特棘龙', 'ダイナレスラー・ギガ・スピノサバット', 'Synchro Monster', 'Dinosaur', 'EARTH', 8, 3000, NULL, '恐龙族调整＋调整以外的怪兽1只以上 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：只要这张卡在怪兽区域存在，对方不能选择其他怪兽作为攻击对象。 ③：1回合1次，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。 ④：这张卡被战斗·效果破坏的场合，可以作为代替把自己场上1张卡破坏。'),
(61269611, 'Dinowrestler Iguanodraka', '恐龙摔跤手・德拉卡禽龙', 'ダイナレスラー・イグアノドラッカ', 'Effect Monster', 'Dinosaur', 'EARTH', 6, 2000, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡以外的1只恐龙族怪兽丢弃才能发动。这张卡从手卡特殊召唤。 ②：把自己场上1只恐龙族怪兽解放，以原本卡名和那只怪兽不同的自己墓地1只「恐龙摔跤手」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(77967790, 'Dinowrestler King T Wrextle', '恐龙摔跤手・王者・角力暴龙', 'ダイナレスラー・キング・Tレッスル', 'Link Monster', 'Dinosaur', 'EARTH', NULL, 3000, NULL, '「恐龙摔跤手」怪兽2只以上 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：只要这张卡在怪兽区域存在，对方不能选择其他怪兽作为攻击对象。 ③：对方战斗阶段开始时，以对方场上1只攻击表示怪兽为对象才能发动。这次战斗阶段中，对方若不用那只怪兽攻击宣言，则不能用其他怪兽攻击宣言。没有攻击宣言的场合，作为对象的怪兽在那次战斗阶段结束时破坏。'),
(54446813, 'Dinowrestler Martial Ampelo', '恐龙摔跤手・武术葡萄园龙', 'ダイナレスラー・マーシャルアンペロ', 'Effect Monster', 'Dinosaur', 'EARTH', 1, 600, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的其他的「恐龙摔跤手」怪兽和持有那个攻击力以上的攻击力的对方怪兽进行战斗的伤害计算时，把手卡·场上的这张卡送去墓地才能发动。那只自己怪兽不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害变成一半。 ②：对方怪兽的攻击宣言时把墓地的这张卡除外才能发动。从卡组把「恐龙摔跤手·武术葡萄园龙」以外的1只「恐龙摔跤手」怪兽加入手卡。');